#!/usr/bin/env node
/**
 * Regenerates `review.md` — the generated mirror of `AGENTS.md`.
 *
 *   node scripts/sync-review-md.mjs           # write review.md
 *   node scripts/sync-review-md.mjs --check   # fail if review.md is out of sync (CI)
 */
import { readFileSync, writeFileSync } from "node:fs";

const BANNER = [
  "<!--",
  "  Generated copy of AGENTS.md — the single source of truth for this project's",
  "  agent/reviewer reference. Do NOT edit this file directly: edit AGENTS.md and",
  "  regenerate with:  node scripts/sync-review-md.mjs",
  "-->",
  "",
  "",
].join("\n");

const toLf = (text) => text.replace(/\r\n/g, "\n");

const agents = toLf(readFileSync("AGENTS.md", "utf8"));
const expected = BANNER + agents;

if (process.argv.includes("--check")) {
  const current = toLf(readFileSync("review.md", "utf8"));
  if (current !== expected) {
    console.error("review.md is out of sync with AGENTS.md — run: node scripts/sync-review-md.mjs");
    process.exit(1);
  }
  console.log("review.md is in sync with AGENTS.md");
} else {
  writeFileSync("review.md", expected, "utf8");
  console.log("Wrote review.md");
}
